package ml.melun.mangaview.ui.library

import android.graphics.BitmapFactory
import android.util.Base64
import androidx.compose.ui.graphics.ImageBitmap
import androidx.compose.ui.graphics.asImageBitmap

internal object LegacySiteArtwork {
    val wfwf: ImageBitmap by lazy { decode(WFWF) }
    val ntk: ImageBitmap by lazy { decode(NTK) }

    private fun decode(value: String): ImageBitmap {
        val bytes = Base64.decode(value, Base64.DEFAULT)
        return requireNotNull(BitmapFactory.decodeByteArray(bytes, 0, bytes.size)).asImageBitmap()
    }

    private const val WFWF = ""
    private const val NTK = ""
}
